import {readFile} from 'node:fs/promises';
import {validatedQuery, savedFilterInput, choice} from '../../../shared/src/index.js';
import {query} from '../client.js';

export const SEARCH_HELP = `crew search [QUERY words ...] --org ORG [--project PROJECT] [--limit N] [--cursor CURSOR]
crew search --query 'status:active AND assignee:@me' --org ORG
crew search --query-file FILE --org ORG [--all]
crew search suggest [QUERY ...] --org ORG [--caret N]
crew search check [QUERY ...]
Search matches token prefixes in keys, titles, labels, descriptions and comments.
Quoted text matches a contiguous phrase. NOT binds before AND, then OR; use parentheses.
Fields: status:, assignee:@me|unassigned|ID, label:, project:, priority>=0..4,
created>YYYY-MM-DD, updated<YYYY-MM-DD. Comparisons support =, !=, <, <=, >, >= for dates and priority.
Search lists include total, highlights, facets and nextCursor. --all traverses every page.
Results and suggestions obey your current project access and insight:read token scope.`;
export const FILTER_HELP = `crew filter list --org ORG [--visibility personal|team|all] [--team TEAM] [--owned true|false] [--limit N] [--cursor CURSOR]
crew filter show FILTER
crew filter create --org ORG --name NAME [--query QUERY|--query-file FILE] [--description TEXT]
                   [--visibility personal|team] [--team TEAM]
crew filter edit FILTER [--name NAME] [--query QUERY|--query-file FILE] [--description TEXT]
                        [--visibility personal|team] [--team TEAM|none] [--revision N]
crew filter run FILTER [--limit N] [--cursor CURSOR] [--all]
crew filter delete FILTER --yes
crew filter options --org ORG
Team filters require current membership in that same-organization team. Only creators edit/delete.
A personal filter is private; passing --visibility personal clears its team.
Use --revision from the previous response to reject an intervening edit.
--owned true lists only your filters; --owned false includes all currently visible filters.
Pass an explicit true or false value (also --owned=true|false); other values are rejected.`;

function required(value, name, help) {
  if (value == null || value === '' || value === true) throw new Error('Missing ' + name + '\n' + help);
  return value;
}

async function queryInput(args, options) {
  if (options.query !== undefined && options['query-file']) throw new Error('Choose either --query or --query-file');
  let source;
  if (options['query-file']) source = await readFile(required(options['query-file'], 'query file', SEARCH_HELP), 'utf8');
  else source = options.query !== undefined ? required(options.query, 'query text', SEARCH_HELP) : args.join(' ');
  return validatedQuery(source).query;
}

export async function collectSearchPages(client, path, parameters, all = false) {
  const first = await client.get(path + query(parameters));
  if (!all || !first.nextCursor) return first;
  const items = [...first.items];
  const seen = new Set();
  let cursor = first.nextCursor;
  while (cursor) {
    if (seen.has(cursor)) throw new Error('Server repeated a search cursor; traversal stopped');
    seen.add(cursor);
    const page = await client.get(path + query({...parameters, cursor}));
    items.push(...page.items);
    cursor = page.nextCursor;
  }
  return {...first, items, nextCursor: null};
}

export async function searchCommand({args, options, client, print}) {
  if (args[0] === 'help') {print(SEARCH_HELP); return;}
  if (args[0] === 'check') {
    const source = await queryInput(args.slice(1), options);
    print({query: source, ast: validatedQuery(source).ast, valid: true});
    return;
  }
  const orgId = required(options.org, '--org organization id', SEARCH_HELP);
  if (args[0] === 'suggest') {
    const source = options.query ?? args.slice(1).join(' ');
    print(await client.get('/search/suggestions' + query({orgId, projectId: options.project, q: source, caret: options.caret})));
    return;
  }
  const source = await queryInput(args, options);
  print(await collectSearchPages(client, '/search', {orgId, projectId: options.project, q: source, limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
}
searchCommand.help = SEARCH_HELP;

async function filterBody(options, {partial = false} = {}) {
  const body = {};
  const map = {org: 'orgId', name: 'name', description: 'description', visibility: 'visibility', team: 'teamId'};
  for (const [option, field] of Object.entries(map)) {
    if (Object.hasOwn(options, option)) body[field] = options[option];
  }
  if (body.teamId === 'none' || body.visibility === 'personal') body.teamId = null;
  if (options.query !== undefined || options['query-file']) body.query = await queryInput([], options);
  return savedFilterInput(body, {partial});
}

export async function filterCommand({args, options, client, print}) {
  const [action = 'list', id] = args;
  if (action === 'help') {print(FILTER_HELP); return;}
  if (action === 'list' || action === 'options') {
    const orgId = required(options.org, '--org organization id', FILTER_HELP);
    const owned = options.owned === undefined ? undefined : choice(options.owned, '--owned', ['true', 'false']);
    print(await client.get('/filters' + (action === 'options' ? '/options' : '') + query({orgId, visibility: options.visibility, teamId: options.team, owned, limit: options.limit, cursor: options.cursor})));
    return;
  }
  if (action === 'create') {
    print(await client.post('/filters', await filterBody(options)));
    return;
  }
  required(id, 'saved filter id', FILTER_HELP);
  const path = '/filters/' + encodeURIComponent(id);
  if (action === 'show') {print(await client.get(path)); return;}
  if (action === 'run') {
    print(await collectSearchPages(client, path + '/search', {limit: options.limit, cursor: options.cursor}, Boolean(options.all)));
    return;
  }
  if (action === 'edit') {
    const body = await filterBody(options, {partial: true});
    if (!Object.keys(body).length) throw new Error('Supply at least one field to edit\n' + FILTER_HELP);
    if (options.revision !== undefined) body.expectedRevision = options.revision;
    print(await client.patch(path, body));
    return;
  }
  if (action === 'delete') {
    if (!options.yes) throw new Error('Use --yes to delete a saved filter');
    print(await client.delete(path));
    return;
  }
  throw new Error('Unknown filter action: ' + action + '\n' + FILTER_HELP);
}
filterCommand.help = FILTER_HELP;

export const insightSearchCommands = {search: searchCommand, filter: filterCommand};

import {useEffect, useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Page, Button, Notice, Loading, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {filterReturnLocation, filterViewLocation} from './filter-view.js';
import {createRequestGuard} from './request-guard.js';
import {createPlanningScope} from '../work/planning-actions.js';
import {useScopedLoad} from './scoped-load.js';
import {FilterForm} from './filter-form.jsx';
import {SearchResults} from './search-results.jsx';
import {previousSearchPage, nextSearchPage} from './search-state.js';

export function FilterDetailPage(props) {
  const owner = useRef({generation: 0});
  const identity = JSON.stringify([props.params.filterId, props.query.run, props.query.returnTo]);
  if (owner.current.api !== props.api || owner.current.identity !== identity) owner.current = {api: props.api, identity, generation: owner.current.generation + 1};
  return <FilterResource key={owner.current.generation} {...props}/>;
}
function FilterResource({api, params, query, navigate}) {
  const id = params.filterId;
  const path = '/filters/' + encodeURIComponent(id);
  const [record, setRecord] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [results, setResults] = useState(null);
  const [history, setHistory] = useState(['']);
  const [editing, setEditing] = useState(null);
  const [unavailable, setUnavailable] = useState(false);
  const reads = useRef(createRequestGuard()).current;
  const actions = useRef(createPlanningScope()).current;
  const runs = useRef(createPlanningScope()).current;
  const discardRef = useRef(() => true);
  const editor = useRef(null);
  const alive = useRef(true);
  let returnTo, returnError;
  try {returnTo = filterReturnLocation(query.returnTo, record?.orgId);}
  catch {returnTo = filterViewLocation({orgId: record?.orgId}); returnError = 'Ignored invalid saved-filter return view.';}
  const returnContext = query.returnTo !== undefined && !returnError ? returnTo : undefined;
  const options = useScopedLoad(record?.orgId ?? '', () => record ? api.get('/filters/options?orgId=' + encodeURIComponent(record.orgId)) : {teams: []});
  useLayoutEffect(() => () => {alive.current = false; editor.current = null; reads.invalidate(); actions.dispose(); runs.dispose();}, []);
  useEffect(() => {load();}, []);
  function lost(failure) {
    setError(failure); setResults(null); setHistory(['']);
    if ([401, 403, 404].includes(failure.status)) {setRecord(null); setUnavailable(true);}
  }
  async function load() {
    const ticket = reads.begin();
    setLoading(true); setError(null);
    try {
      const result = await api.get(path, {signal: ticket.signal});
      if (!reads.current(ticket)) return;
      setRecord(result.filter); setUnavailable(false);
      if (query.run === '1') run(['']);
    } catch (failure) {if (reads.current(ticket)) lost(failure);}
    finally {if (reads.current(ticket)) setLoading(false);}
  }
  async function run(nextHistory = ['']) {
    if (unavailable) return;
    const operation = runs.begin();
    if (!operation) return;
    reads.invalidate(); setLoading(false);
    setBusy(true); setError(null); setMessage('');
    try {
      const parameters = new URLSearchParams({limit: '25'});
      if (nextHistory.at(-1)) parameters.set('cursor', nextHistory.at(-1));
      const data = await api.get(path + '/search?' + parameters, {signal: operation.signal});
      if (!operation.current()) return;
      setRecord(data.filter); setResults(data); setHistory(nextHistory);
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  function closeEditor() {editor.current = null; setEditing(null);}
  async function openEditor(copy) {
    if (unavailable || !discardRef.current()) return;
    const operation = actions.begin();
    if (!operation) return;
    closeEditor(); setBusy(true); setError(null);
    try {
      const data = await api.get(path, {signal: operation.signal});
      if (!operation.current()) return;
      setRecord(data.filter);
      const source = copy ? {orgId: data.filter.orgId, name: data.filter.name.slice(0, 95) + ' copy', description: data.filter.description, query: data.filter.query, visibility: 'personal', teamId: ''} : data.filter;
      const form = {source, copy}; editor.current = form; setEditing(form);
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function remove() {
    if (unavailable || !discardRef.current()) return;
    const operation = actions.begin();
    if (!operation) return;
    setBusy(true); setError(null);
    try {
      await api.delete(path, undefined, {signal: operation.signal});
      if (!operation.current()) return;
      navigate(returnTo);
    } catch (failure) {if (operation.current()) lost(failure);}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  return <Page title={record?.name ?? 'Saved filter'} actions={<a href={'#' + returnTo} onClick={event => {if (!discardRef.current()) event.preventDefault();}}>Saved filters</a>}>
    <Notice error={error}/><Notice>{message}</Notice><Notice>{returnError}</Notice>
    {loading && <Loading/>}
    {unavailable && <Notice>This saved filter is unavailable with your current access. Any local draft remains below; inaccessible records and results have been cleared.</Notice>}
    {record && <article aria-label="Saved filter details">
      <p>{record.description || 'No description'}</p><pre aria-label="Saved query">{record.query || 'All accessible issues'}</pre>
      <dl><dt>Visibility</dt><dd>{record.visibility === 'personal' ? 'Personal · only you' : 'Team shared'}</dd>
        {record.visibility === 'team' && <><dt>Team</dt><dd>{options.data?.teams.find(team => team.id === record.teamId)?.name ?? 'Shared team'}</dd></>}
        <dt>Creator</dt><dd>{record.canEdit ? 'Created by you' : 'Created by another team member'}</dd>
        <dt>Revision</dt><dd>{record.revision}</dd><dt>Created</dt><dd>{new Date(record.createdAt).toLocaleString()}</dd><dt>Updated</dt><dd>{new Date(record.updatedAt).toLocaleString()}</dd></dl>
      <p>Run always reads the currently saved query with your current access. A changed query can invalidate an older page cursor; run again to start at its first page.</p>
      <div className="actions"><Button busy={busy} onClick={() => run([''])}>Run filter</Button><Button disabled={busy} onClick={load}>Refresh saved filter</Button>
        <Button disabled={busy} onClick={() => openEditor(true)}>Create personal copy</Button>
        {record.canEdit && <><Button disabled={busy} onClick={() => openEditor(false)}>Edit saved filter</Button><ConfirmButton disabled={busy} message={'Delete saved filter “' + record.name + '”?'} onConfirm={remove}>Delete saved filter</ConfirmButton></>}
      </div>
    </article>}
    {editing && <FilterForm api={api} filter={editing.source} orgId={editing.source.orgId} copy={editing.copy} disabled={unavailable} teams={options.data?.teams} discardRef={discardRef}
      onCancel={closeEditor} onUnavailable={() => {reads.invalidate(); runs.dispose(); actions.dispose(); setBusy(false); setLoading(false); setRecord(null); setResults(null); setHistory(['']); setUnavailable(true);}}
      onSaved={filter => {
        if (!alive.current || editor.current !== editing) return;
        closeEditor(); setResults(null); setHistory(['']);
        if (editing.copy) navigate(routeLink('/filters/' + encodeURIComponent(filter.id), {returnTo: returnContext}).slice(1));
        else {setRecord(filter); setMessage('Saved “' + filter.name + '”.');}
      }}/>}
    {results && !unavailable && <section aria-label="Search results">
      <p>Results for <code>{results.filter.query || 'all accessible issues'}</code> · saved revision {results.filter.revision}</p>
      <SearchResults results={results} history={history} busy={busy} onPrevious={() => run(previousSearchPage(history))} onNext={() => run(nextSearchPage(history, results.nextCursor))}/>
    </section>}
  </Page>;
}

import {choice, fields, text} from '../../../../shared/src/index.js';
import {parseLocation, routeLink} from '../../router.js';

const keys = ['orgId', 'q', 'visibility', 'teamId', 'owned', 'cursor'];
function viewText(value, field, max) {
  const result = text(value ?? '', field, {min: 0, max});
  if (/[\u0000-\u001f\u007f]/.test(result)) throw new Error('Invalid saved-filter ' + field);
  return result;
}
export function filterView(input = {}) {
  fields(input, keys);
  const view = {
    orgId: viewText(input.orgId, 'orgId', 100),
    q: viewText(input.q, 'q', 100),
    visibility: choice(input.visibility, 'visibility', ['all', 'personal', 'team'], 'all'),
    teamId: viewText(input.teamId, 'teamId', 100),
    owned: choice(input.owned, 'owned', ['true', 'false'], 'false'),
    cursor: viewText(input.cursor, 'cursor', 4000)
  };
  if (view.cursor && !/^[A-Za-z0-9_-]+$/.test(view.cursor)) throw new Error('Invalid saved-filter cursor');
  if (!view.orgId && (view.teamId || view.cursor)) throw new Error('A saved-filter team or page needs an organization');
  return view;
}
export function filterViewLocation(input = {}) {
  const view = filterView(input);
  return routeLink('/filters', {
    orgId: view.orgId, q: view.q, visibility: view.visibility === 'all' ? '' : view.visibility,
    teamId: view.teamId, owned: view.owned === 'false' ? '' : view.owned, cursor: view.cursor
  }).slice(1);
}
export function filterReturnLocation(value, orgId = '') {
  if (value === undefined) return filterViewLocation({orgId});
  if (typeof value !== 'string' || value.includes('#') || /%(?![\da-f]{2})/i.test(value)) throw new Error('Invalid saved-filter return view');
  const location = parseLocation(value);
  if (location.pathname !== '/filters') throw new Error('Return view must be a saved-filter list');
  const search = value.includes('?') ? value.slice(value.indexOf('?') + 1) : '';
  const parameters = new URLSearchParams(search);
  if ([...parameters.keys()].length !== new Set(parameters.keys()).size) throw new Error('Duplicate saved-filter return field');
  return filterViewLocation(location.query);
}

import {useEffect, useLayoutEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad, ConfirmButton} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {filterView, filterViewLocation} from './filter-view.js';
import {EntityPicker} from './selectors.jsx';
import {FilterForm} from './filter-form.jsx';
import {useScopedLoad} from './scoped-load.js';
import {createRequestGuard} from './request-guard.js';
import {createPlanningScope} from '../work/planning-actions.js';

export function FiltersPage(props) {
  const owner = useRef({generation: 0});
  const predecessors = useRef(new Map()).current;
  let view, error;
  try {view = filterView(props.query);} catch (failure) {error = failure;}
  const identity = view ? filterViewLocation(view) : JSON.stringify(props.query);
  if (owner.current.api !== props.api || owner.current.identity !== identity) owner.current = {api: props.api, identity, generation: owner.current.generation + 1};
  if (error) return <Page title="Saved filters"><Notice error={error}/><a href={routeLink('/filters')}>Reset invalid saved-filter view</a></Page>;
  return <FiltersOrganization key={owner.current.generation} {...props} view={view} predecessors={predecessors}/>;
}
function FiltersOrganization({api, view, navigate, predecessors}) {
  const organizations = useLoad(() => api.get('/insight/options?type=organizations&limit=1'), []);
  const orgId = view.orgId;
  const discardRef = useRef(() => true);
  const [pickerVersion, setPickerVersion] = useState(0);
  useEffect(() => {if (!orgId && organizations.data?.items.length) navigate(filterViewLocation({...view, orgId: organizations.data.items[0].id}));}, [organizations.data]);
  function changeOrg(value) {
    if (value === orgId) return;
    if (discardRef.current()) navigate(filterViewLocation({orgId: value})); else setPickerVersion(version => version + 1);
  }
  return <Page title="Saved filters" actions={<a href={routeLink('/search', {orgId})} onClick={event => {if (!discardRef.current()) event.preventDefault();}}>Search issues</a>}>
    <Notice error={organizations.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Join an organization before saving a filter.</Empty> : <>
      <EntityPicker key={pickerVersion} api={api} type="organizations" label="Organization" value={orgId} required onChange={changeOrg}/>
      <FiltersScope api={api} view={view} discardRef={discardRef} navigate={navigate} predecessors={predecessors}/>
    </>}
  </Page>;
}
function FiltersScope({api, view, discardRef, navigate, predecessors}) {
  const {orgId, cursor} = view;
  const location = filterViewLocation(view);
  const [draft, setDraft] = useState({...view, cursor: ''});
  const [editing, setEditing] = useState(null);
  const [error, setError] = useState(null);
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const [opening, setOpening] = useState('');
  const [hidden, setHidden] = useState(() => new Set());
  const editor = useRef(null);
  const alive = useRef(true);
  const pendingEdit = useRef(null);
  const editGuard = useRef(createRequestGuard()).current;
  const mutations = useRef(createPlanningScope()).current;
  const options = useScopedLoad(orgId, () => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: []});
  const listing = useScopedLoad(location, () => orgId ? api.get('/filters?' + new URLSearchParams({...view, limit: '25'})) : {items: [], total: 0});
  useLayoutEffect(() => () => {alive.current = false; editor.current = null; editGuard.invalidate(); mutations.dispose(); discardRef.current = () => true;}, []);
  function hide(id) {setHidden(previous => new Set([...previous, id]));}
  const visibleItems = listing.data?.items.filter(filter => !hidden.has(filter.id)) ?? [];
  function setEditor(value) {editor.current = value; setEditing(value);}
  function replaceEditor(value) {
    if (!discardRef.current()) return;
    editGuard.invalidate(); pendingEdit.current = null; setOpening(''); setEditor(value);
  }
  async function remove(filter) {
    const operation = mutations.begin();
    if (!operation) return;
    editGuard.invalidate(); pendingEdit.current = null; setOpening('');
    setError(null); setBusy(true);
    try {
      await api.delete('/filters/' + encodeURIComponent(filter.id), undefined, {signal: operation.signal});
      if (!operation.current()) return;
      hide(filter.id); if (editor.current?.id === filter.id) setEditor(null);
      setMessage('Deleted “' + filter.name + '”.'); listing.reload();
    } catch (failure) {if (operation.current()) {setError(failure); if ([401, 403, 404].includes(failure.status)) {hide(filter.id); listing.reload();}}}
    finally {if (operation.current()) {setBusy(false); operation.finish();}}
  }
  async function edit(filter) {
    if (pendingEdit.current === filter.id || !discardRef.current()) return;
    setEditor(null); setError(null); pendingEdit.current = filter.id; setOpening(filter.name);
    const ticket = editGuard.begin();
    try {
      const result = await api.get('/filters/' + encodeURIComponent(filter.id), {signal: ticket.signal});
      if (editGuard.current(ticket)) setEditor(result.filter);
    } catch (failure) {if (editGuard.current(ticket)) {setError(failure); if ([401, 403, 404].includes(failure.status)) {hide(filter.id); listing.reload();}}}
    finally {if (editGuard.current(ticket)) {pendingEdit.current = null; setOpening('');}}
  }
  function follow(event) {if (!discardRef.current()) event.preventDefault();}
  function go(input, previous) {
    let next;
    try {next = filterViewLocation(input);} catch (failure) {setError(failure); return;}
    if (!discardRef.current()) return;
    if (previous !== undefined) predecessors.set(next, previous);
    if (next === location) {listing.reload(); return;}
    alive.current = false; editGuard.invalidate(); mutations.dispose();
    navigate(next);
  }
  function apply(event) {event.preventDefault(); go(draft);}
  const update = (field, value) => setDraft(previous => ({...previous, [field]: value}));
  const unsent = filterViewLocation({...view, cursor: ''}) !== filterViewLocation(draft);
  return <>
    <Notice error={error ?? listing.error ?? options.error}/><Notice>{message}</Notice>
    {opening && <Notice>Opening “{opening}”…</Notice>}
    <form className="search-controls" aria-label="Saved-filter view" onSubmit={apply}>
      <Field label="Find a saved filter"><input value={draft.q} maxLength={100} placeholder="Name or description" onInput={event => update('q', event.currentTarget.value)}/></Field>
      <Field label="Visibility"><select value={draft.visibility} onChange={event => update('visibility', event.currentTarget.value)}>
        <option value="all">Personal and shared</option><option value="personal">Personal</option><option value="team">Team shared</option>
      </select></Field>
      <Field label="Team"><select value={draft.teamId} onChange={event => update('teamId', event.currentTarget.value)}>
        <option value="">All my teams</option>{options.data?.teams.map(team => <option key={team.id} value={team.id}>{team.name}</option>)}
      </select></Field>
      <label><input type="checkbox" checked={draft.owned === 'true'} onChange={event => update('owned', String(event.currentTarget.checked))}/>Created by me</label>
      <p role="status">{unsent ? 'View changes are not applied. Apply to start at the first page.' : 'Showing the applied view from this URL.'}</p>
      <Button type="submit" disabled={!orgId || busy}>Apply view</Button>
      <Button type="button" disabled={!orgId || busy} onClick={() => go({orgId})}>Reset view</Button>
    </form>
    <p>Copy the current URL to reopen this applied view and page. Browser Back, Forward or reload can replace local unsaved drafts.</p>
    <Button disabled={!orgId || busy || listing.loading} onClick={listing.reload}>Refresh filters</Button>
    <Button disabled={!orgId || busy || Boolean(options.error)} onClick={() => replaceEditor({})}>Create saved filter</Button>
    {editing && <FilterForm api={api} orgId={orgId} filter={editing} teams={options.data?.teams} discardRef={discardRef}
      onCancel={() => setEditor(null)} onUnavailable={() => {if (editing.id) hide(editing.id); listing.reload();}} onSaved={filter => {
        if (!alive.current || editor.current !== editing) return;
        setEditor(null); setMessage('Saved “' + filter.name + '”.'); listing.reload();
      }}/>}
    {listing.loading ? <Loading/> : listing.error ? null : !visibleItems.length ? <Empty>No saved filters in this view. Create one or ask a teammate to share one.</Empty> : <>
      <p>{listing.data.total} accessible filters</p>
      <ul className="saved-filters">{visibleItems.map(filter => <li key={filter.id}>
        <article><h2><a href={routeLink('/filters/' + encodeURIComponent(filter.id), {returnTo: location})} onClick={follow}>{filter.name}</a></h2>
          {filter.description && <p>{filter.description}</p>}<p>Updated {new Date(filter.updatedAt).toLocaleString()}</p>
          <pre>{filter.query || 'All accessible issues'}</pre>
          <p>{filter.visibility === 'personal' ? 'Personal' : 'Team: ' + (options.data?.teams.find(team => team.id === filter.teamId)?.name ?? 'Shared team')} · revision {filter.revision}</p>
          <div className="actions"><a className="button" href={routeLink('/filters/' + encodeURIComponent(filter.id), {run: '1', returnTo: location})} onClick={follow}>Run filter</a>
            {filter.canEdit && <><Button disabled={busy} onClick={() => edit(filter)}>Edit</Button>
              <ConfirmButton disabled={busy} message={'Delete saved filter “' + filter.name + '”?'} onConfirm={() => {if (discardRef.current()) remove(filter);}}>Delete</ConfirmButton></>}
          </div>
        </article>
      </li>)}</ul>
    </>}
    <div className="actions">
      <Button disabled={busy || !cursor} onClick={() => go({...view, cursor: ''})}>First page</Button>
      <Button disabled={busy || !predecessors.has(location)} onClick={() => go({...view, cursor: predecessors.get(location)})}>Previous</Button>
      <span>{cursor ? 'Later page' : 'First page'}</span>
      <Button disabled={busy || listing.loading || !listing.data?.nextCursor} onClick={() => go({...view, cursor: listing.data.nextCursor}, cursor)}>Next</Button>
    </div>
    {cursor && !predecessors.has(location) && <p>The previous page is unavailable after opening this URL. Use First page, or browser Back to revisit a known view.</p>}
  </>;
}
